# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">2. TEMA: KELİMELERİN RİTMİ — GAZEL VE KASİDE NAZIM BİÇİMLERİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">GAZEL (DİVAN EDEBİYATI LİRİK ŞİİRİ)</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Nazım Birimi ve Ölçü: Beyit (5-15 beyit) · Aruz ölçüsü</text>\n  <text x="35" y="108" font-size="11.2" fill="#1e3a8a">• Kafiye Şeması: aa - ba - ca - da - ea ...</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">• Bölümleri: Matla (ilk beyit - aa), Makta (son beyit),</text>\n  <text x="35" y="146" font-size="11.2" fill="#1e3a8a">  Beytü\'l-gazel / Şah beyit (en güzel beyit), Mahlas beyti</text>\n  <text x="35" y="168" font-size="11.2" font-weight="bold" fill="#1e40af">• Konu: Aşk, güzellik, ayrılık, tasavvuf (Fuzûlî, Bâkî)</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">ARA METİN: KASİDE (ÖVGÜ VE YERGİ ŞİİRİ)</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Nazım Birimi ve Ölçü: Beyit (33-99 beyit) · Aruz ölçüsü</text>\n  <text x="370" y="108" font-size="11.2" fill="#14532d">• Kafiye Şeması: aa - ba - ca - da ... (Matla, Makta, Taç beyit)</text>\n  <text x="370" y="128" font-size="11.2" fill="#14532d">• 6 Bölümü: Nesib/Teşbib (betimleme), Girizgâh, Methiye</text>\n  <text x="370" y="146" font-size="11.2" fill="#14532d">  (övgü), Tegazzül (gazel), Fahriye (şairin övünmesi), Dua</text>\n  <text x="370" y="168" font-size="11.2" font-weight="bold" fill="#166534">• Konularına Göre: Tevhit, Münacat, Naat, Methiye (Nef\'î)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Konu bütünlüğü olan gazele \'yek-ahenk\', her beyti aynı üstün güzellikte olana \'yek-avaz\', iç kafiyeliye \'musammat\' denir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SAF (ÖZ) ŞİİR ANLAYIŞI VE ŞİİRDE AHENK UNSURLARI</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">SAF (ÖZ) ŞİİR ANLAYIŞININ İLKELERİ</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Temel İlke: «Şiirde her şeyden önce musiki (ritim)»</text>\n  <text x="35" y="108" font-size="11.2" fill="#713f12">• Amaç: Öğreticilik (didaktik/ideolojik mesaj) değil,</text>\n  <text x="35" y="126" font-size="11.2" fill="#713f12">  estetik haz uyandıran kusursuz ve güzel şiir yazmak</text>\n  <text x="35" y="146" font-size="11.2" fill="#713f12">• Özellik: İçsel ahenk, imge, çağrışım ve ses uyumu</text>\n  <text x="35" y="168" font-size="11.2" font-weight="bold" fill="#854d0e">• Temsilciler: Ahmet Haşim, Yahya Kemal, Necip Fazıl, Dıranas</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">KELİMELERİN RİTMİNİ KURAN AHENK UNSURLARI</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• 1. Ölçü (Vezin): Aruz (açık/kapalı), Hece (durak), Serbest</text>\n  <text x="370" y="110" font-size="11.2" fill="#581c87">• 2. Redif: Dize sonlarında aynı görevli ek/kelime tekrarı</text>\n  <text x="370" y="132" font-size="11.2" fill="#581c87">• 3. Kafiye (Uyak): Yarım (1), Tam (2), Zengin (3+), Tunç, Cinaslı</text>\n  <text x="370" y="154" font-size="11.2" fill="#581c87">• 4. Ses Tekrarları: Aliterasyon (ünsüz) ve Asonans (ünlü)</text>\n  <text x="370" y="176" font-size="11.2" fill="#581c87">• 5. Nakarat, Kelime Tekrarları ve İç Kafiye</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Şiirde önce dize sonundaki redif bulunur; rediften önceki kök/gövdede yer alan ses benzerliklerinde kafiye aranır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">OKUMAYI YÖNETME VE ANLAM OLUŞTURMA SÜRECİ (TDE2.1 &amp; TDE2.2)</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">OKUMAYI YÖNETME VE ANLAM OLUŞTURMA (TDE2.1-2.2)</text>\n  <text x="35" y="88" font-size="11" fill="#7c2d12">• TDE2.1.1: Okuma amacını belirleme; başlık ve görselden</text>\n  <text x="35" y="105" font-size="11" fill="#7c2d12">  metnin türü, dönemi ve temasına yönelik tahmin yapma</text>\n  <text x="35" y="125" font-size="11" fill="#7c2d12">• TDE2.1.2: Şiir türüne uygun sesli/vurgulu okuma seçimi</text>\n  <text x="35" y="145" font-size="11" fill="#7c2d12">• TDE2.2.1-3: Ön bilgilerle bağ kurma, bağlamdan mazmun</text>\n  <text x="35" y="162" font-size="11" fill="#7c2d12">  ve söz varlığı anlamını tahmin etme, ana duyguyu bulma</text>\n  <text x="35" y="182" font-size="11" fill="#7c2d12">• TDE2.2.4-5: Gazel, kaside ve saf şiiri karşılaştırma</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">DİVAN ŞİİRİ MAZMUNLARI VE SÖZ SANATLARI</text>\n  <text x="370" y="88" font-size="11" fill="#164e63">• Mazmun (Kalıplaşmış İmge): Gül (sevgili), Bülbül (âşık),</text>\n  <text x="370" y="106" font-size="11" fill="#164e63">  Ok/Kirpik (müjgân), Yay/Kaş (kemân), Servi (uzun boy)</text>\n  <text x="370" y="126" font-size="11" fill="#164e63">• Teşbih (Benzetme) ve İstiare (Açık/Kapalı Eğretileme)</text>\n  <text x="370" y="146" font-size="11" fill="#164e63">• Teşhis (Kişileştirme) ve Hüsnütalil (Güzel Nedene Bağlama)</text>\n  <text x="370" y="166" font-size="11" fill="#164e63">• Tenasüp (Uygunluk), Tezat (Karşıtlık) ve Mübalağa (Abartma)</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Okuyucu; gazel, kaside ve saf şiir metinlerini biçim, ahenk, dönem zihniyeti ve üslup ölçütlerine göre sınıflandırır.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
